            last_ret_s = ret_s[-1]
            last_ret_e = ret_e[-1]
            last_residual = last_ret_s - (alpha + beta * last_ret_e)

            # Historical residuals for standardisation
            all_residuals = ret_s - (alpha + beta * ret_e)
