        for t in tickers:
            df_stock = histories.get(t)
            df_etf = histories.get("XLK")
            if df_stock is not None and df_etf is not None and len(df_stock) >= 60:
                closes_s = df_stock["Close"].astype(float).values
                closes_e = df_etf["Close"].astype(float).values

